 *
 * @param {Array} arr0 - Rectangular nested array (multidimensional).
 * @param {number} k - Remove every k-th element (k >= 1). If k === 1, that axis becomes empty.
 * @param {number} dim - Axis (0-based) to remove elements from.
 * @returns {Array} - Resulting nested array after removals.
 *
 * Example:
 *   removeEveryKth([[1,2,3,4],[5,6,7,8]], 2, 1)
 *   // removes every 2nd element along axis 1 -> [[1,3],[5,7]]
 */
export function removeEveryKth(arr0, k, dim = 0) {
  if (!Number.isInteger(k) || k <= 0) {
    throw new Error('k must be a positive integer (>= 1).');
  }
  if (!Number.isInteger(dim) || dim < 0) {
    throw new Error('dim must be a non-negative integer.');
  }

  // Convert to tensor
  const t = tf.tensor(arr0);
  const shape = t.shape;

