  if (kept.length === dimSize) {
    return arr0;
  }

  // Gather along axis 'dim' with kept indices
  const idxTensor = tf.tensor1d(kept, 'int32');
  const out = t.gather(idxTensor, dim);

  return out.arraySync();
}

