```javascript
import { z } from "zod";

/**
 * Reorder an array of objects so they appear in the sequence defined by 'order'.
 *
 * @param {Array<Object>} items - Collection of items (each must contain an identifier property).
 * @param {Array<string|number>} order - Sequence of identifier values to order by.
 * @param {Object} options - Optional configuration.
 * @param {string} options.idKey - Key on each item that holds the identifier (default: 'id').
 * @param {'omit'|'error'|'append'} options.missing - Behavior for ids present in order but not in items (default: 'omit').
 * @param {'preserve'|'first'} options.duplicates - How to handle multiple items with same id (default: 'preserve').
 * @param {boolean} options.keepUnordered - Append items not mentioned in order at the end (default: true).
 * @returns {Array<Object|null>} - Reordered array (may contain null placeholders if missing='append').
 *
 * Throws on invalid inputs (validated via Zod) or when missing='error' and an id is absent.
 */
export function reorderById(items, order, options = {}) {
  // validate inputs
  const optsSchema = z.object({
    idKey: z.string().nonempty().optional(),
    missing: z.enum(["omit", "error", "append"]).optional(),
    duplicates: z.enum(["preserve", "first"]).optional(),
    keepUnordered: z.boolean().optional(),
  }).strict();

  const schema = z.tuple([
    z.array(z.record(z.any())), // items: array of objects
    z.array(z.union([z.string(), z.number()])), // order: array of primitive ids
    optsSchema.optional(),
  ]);

  schema.parse([items, order, options]); // will throw if invalid

  const {
    idKey = "id",
    missing = "omit",
    duplicates = "preserve",
    keepUnordered = true,
  } = options;

  // Build a map from id -> array of items (preserve original relative order)
  const map = new Map();
  const unorderedItems = [];

  for (const item of items) {
    // handle items that don't have the idKey explicitly: treat as unordered item
    if (!Object.prototype.hasOwnProperty.call(item, idKey)) {
      unorderedItems.push(item);
      continue;
    }

    const id = item[idKey];
    if (!map.has(id)) map.set(id, []);
    map.get(id).push(item);
  }

  const result = [];

  for (const id of order) {
    if (!map.has(id) || map.get(id).length === 0) {
      if (missing === "error") {
        throw new Error(`reorderById: id "${String(id)}" specified in order not found in items`);
      } else if (missing === "append") {
        // put placeholder for missing id
        result.push(null);
      } // else 'omit' -> do nothing
      continue;
    }

    const bucket = map.get(id);
    if (duplicates === "first") {
      result.push(bucket[0]);
    } else {
      // preserve: push all items for this id in their original relative order
      for (const it of bucket) result.push(it);
    }

    // remove from map so we know what's left for unordered appending
    map.delete(id);
  }

  // If keepUnordered, append any remaining items (in original items order)
  if (keepUnordered) {
    // Remaining items are those left in map plus those without idKey
    // To preserve original order we iterate original items and include those not yet used.
    const usedSet = new WeakSet(); // for object identity tracking
    for (const out of result) if (out && typeof out === "object") usedSet.add(out);

    for (const item of items) {
      if (usedSet.has(item)) continue;
      // if item had idKey and was consumed, map won't have it; if it wasn't consumed, include it
      if (Object.prototype.hasOwnProperty.call(item, idKey)) {
        const id = item[idKey];
        // if id was specified in order and duplicates==='first' then subsequent duplicates may be left; include them
        if (map.has(id)) {
          const arr = map.get(id);
          // push in original item order (arr preserves original order)
          // but only push items that are still in arr (we use object identity)
          // We'll push all arr items now and remove entry
          for (const it of arr) result.push(it);
          map.delete(id);
          continue;
        }
        // otherwise this item is either already used or its id was in order and duplicates='first' consumed first one,
        // so this item may or may not be desired to append. If it's not used yet, append it.
        if (!usedSet.has(item)) {
          result.push(item);
        }
      } else {
        // item had no idKey — include it
        result.push(item);
      }
    }
  }

  return result;
}
