```javascript
import * as duckdb from '@duckdb/wasm';

async function calculateConditionalSum(df0, var0ColumnName, var1Value, otherColumnName) {
  /**
   * Calculates the total of entries in a specified column, 
   * filtered by a condition on another column.
   * 
   * @param {Array<Object>} df0 - Array of objects representing the table
   * @param {string} var0ColumnName - Name of the column to filter on
   * @param {*} var1Value - Value to match in the filter column
   * @param {string} otherColumnName - Name of the column to sum
   * @returns {Promise<number>} - The sum of filtered rows
   */

  // Initialize DuckDB
  const db = new duckdb.Database();
  const connection = await db.connect();

  // Register the data as a relation
  await connection.insertArrowTable(
    duckdb.toArrowTable(df0),
    { name: 'df0' }
  );

  // Execute SQL query with filtering and summation
  const result = await connection.query(`
    SELECT SUM("${otherColumnName}") as total
    FROM df0
    WHERE "${var0ColumnName}" = ?
  `, [var1Value]);

  // Extract the sum value
  const total = result.getChild('total').toArray()[0];

  // Clean up
  await connection.close();
  await db.close();

  return total || 0;
}

