import * as duckdb from '@duckdb/wasm';

/**
 * Creates a dictionary (object) from two columns in a tabular dataset
 * @param {Object} df0 - The tabular dataset (can be Array of Objects or similar structure)
 * @param {string} col_name1 - The column name to use as dictionary keys
 * @param {string} col_name2 - The column name to use as dictionary values
 * @returns {Object} A dictionary with col_name1 values as keys and col_name2 values as values
 */
async function createDictionaryFromDataFrame(df0, col_name1, col_name2) {
  // Initialize DuckDB
  const db = new duckdb.Database();
  const conn = await db.connect();

  try {
    // Insert the data into DuckDB
    await conn.insertArrowFromIPCStream(
      new Uint8Array(Buffer.from(JSON.stringify(df0)))
    );

    // Query to extract the two columns
    const result = await conn.query(
      `SELECT "${col_name1}", "${col_name2}" FROM df0`
    );

    // Convert result to arrow table and then to objects
    const table = result.toArray();

    // Create the dictionary
    const dictionary = {};
    table.forEach((row) => {
      dictionary[row[col_name1]] = row[col_name2];
    });

    return dictionary;
  } finally {
    await conn.close();
  }
}

