    layout: 'fitColumns',
    addRow: false, // Disable row addition
    resizableRows: false, // Disable row resizing
    resizableColumns: true, // Allow column resizing
    movableColumns: true, // Allow column reordering
    tooltips: true, // Show tooltips
    pagination: 'local', // Disable pagination for this operation
    paginationSize: 1000, // Large enough for reshaping
    data: table.tabulator.getData(), // Get current data
    columns: table.tabulator.getColumns(), // Get current columns
