 *    - removeIndexCols: if true, index columns are removed from stored rows (default true)
 *    - returnFormat: "nestedMap" (default) returns Map<level1, Map<level2, Array<row>>>
 *                    "flatWithTuple" returns an array of rows with an added "_index" array [level1,level2]
 *
 * Returns: object with { result, meta } where `result` is either the nested Map or flat array,
 * and `meta` describes the format and original row count.
 */
export function setTwoLevelIndex(df0, options = {}) {
  const {
    level1 = "str0",
    level2 = "str1",
    removeIndexCols = true,
    returnFormat = "nestedMap", // or "flatWithTuple"
  } = options;

  // Normalize rows: accept Arquero Table or array of objects
  let rows;
  if (df0 && typeof df0.objects === "function") {
    // Arquero Table has objects() to yield array of plain objects
    rows = df0.objects();
  } else if (Array.isArray(df0)) {
    rows = df0;
  } else {
    throw new TypeError("df0 must be an Arquero Table or an array of objects");
  }

  const totalRows = rows.length;

  if (returnFormat === "flatWithTuple") {
    // Return flattened array where each row has _index: [level1, level2]
    const flat = rows.map((r) => {
      const idx1 = r[level1];
      const idx2 = r[level2];
      const copy = { ...r };
      if (removeIndexCols) {
        delete copy[level1];
        delete copy[level2];
      }
      copy._index = [idx1, idx2];
      return copy;
    });
    return {
      result: flat,
      meta: { format: "flatWithTuple", rows: totalRows, indexCols: [level1, level2] },
    };
  }

  // Default: nested Map
  const nested = new Map(); // Map<level1Value, Map<level2Value, Array<row>>>

  for (const row of rows) {
    const k1 = row[level1];
    const k2 = row[level2];

    if (!nested.has(k1)) nested.set(k1, new Map());
    const sub = nested.get(k1);
    if (!sub.has(k2)) sub.set(k2, []);
    const storedRow = removeIndexCols ? (() => {
      const copy = { ...row };
      delete copy[level1];
      delete copy[level2];
      return copy;
    })() : { ...row };

    sub.get(k2).push(storedRow);
  }

  return {
    result: nested,
    meta: { format: "nestedMap", rows: totalRows, indexCols: [level1, level2] },
  };
}

