  const toNumber = (v) => {
    if (v === null || v === undefined || v === '') return 0;
    if (typeof v === 'number') {
      return Number.isFinite(v) ? v : 0;
    }
    // Try to parse numeric strings (trim whitespace)
    const n = Number(String(v).trim());
    return Number.isFinite(n) ? n : 0;
  };

  // Build new rows with summed columns
  const newRows = rows.map((row, rowIdx) => {
    if (!Array.isArray(row)) {
      throw new Error(`Each row must be an array; row ${rowIdx} is not.`);
    }
    const outRow = new Array(uniqueHeaders.length).fill(0);
    for (let j = 0; j < uniqueHeaders.length; j++) {
      const indices = headerToIndices.get(uniqueHeaders[j]);
      let sum = 0;
      for (const idx of indices) {
        // If row shorter than header index, treat missing as 0
        const val = idx < row.length ? row[idx] : 0;
        sum += toNumber(val);
      }
      outRow[j] = sum;
    }
    return outRow;
  });

  const result = { headers: uniqueHeaders, rows: newRows };

  // Optionally produce an Apache Arrow table (numeric columns as Float64)
  if (options && options.returnArrow) {
    // Create Arrow schema fields and builders
