// Add A_perc column using Polars (polars JS must be installed: npm install polars)
function addAperc(table) {
  // load polars
  let pl;
  try {
    pl = require("polars");
  } catch (err) {
    throw new Error("Please install polars: npm install polars");
  }

  // Normalize input to a Polars DataFrame
  let inputWasArray = false;
  let df;
  if (Array.isArray(table)) {
    inputWasArray = true;
    df = pl.DataFrame(table);
  } else if (table && table instanceof pl.DataFrame) {
    df = table;
  } else if (table && typeof table === "object") {
    // try constructing from an object of columns or from plain row-like object
    try {
      df = pl.DataFrame(table);
      inputWasArray = false;
    } catch (e) {
      throw new Error("Unsupported table format. Provide an array of row objects or a polars DataFrame.");
    }
  } else {
    throw new Error("Unsupported table format. Provide an array of row objects or a polars DataFrame.");
  }

  // Build expression: if sum is null or zero -> null, otherwise A / sum
  const aPercExpr = pl
    .when(pl.col("sum").isNull().or(pl.col("sum").eq(0)))
    .then(null)
    .otherwise(pl.col("A").div(pl.col("sum")))
    .alias("A_perc");

