export function assignLabels(input, options = {}) {
  // Validate inputs using zod
  const optsSchema = z.object({
    start: z.number().int().optional().default(0),
    returnMap: z.boolean().optional().default(false),
  });

  const inputSchema = z.array(z.any());

  const parsedOpts = optsSchema.parse(options);
  const arr = inputSchema.parse(input);

