function groupAndSumTable(table, groupByColumn = 'var0') {
  // Using Map for efficient grouping (part of JavaScript standard library)
  const grouped = new Map();

  for (const row of table) {
    const groupKey = row[groupByColumn];

    if (!grouped.has(groupKey)) {
