```javascript
// Install: npm install danfojs-node@latest
const dfd = require("danfojs-node");

/**
 * Fill missing entries in categorical columns with the column mode.
 *
 * @param {dfd.DataFrame} df0 - Input DataFrame (danfo.js).
 * @param {Object} [opts] - Options.
 * @param {boolean} [opts.inplace=false] - If true, modify df0 in place; otherwise return a copy.
 * @param {boolean} [opts.treatEmptyStringAsMissing=false] - Treat "" (empty string) as missing.
 * @returns {dfd.DataFrame} - DataFrame with missing categorical entries filled.
 */
function fillCategoricalModes(df0, opts = {}) {
  const { inplace = false, treatEmptyStringAsMissing = false } = opts;

  if (!df0 || typeof df0.columns === "undefined") {
    throw new Error("fillCategoricalModes: df0 must be a danfo.js DataFrame");
  }

  // Work on a copy unless inplace requested
  const df = inplace ? df0 : df0.copy();

  // Helper to detect missing
  const isMissing = (v) => {
    if (v === null || v === undefined) return true;
    // NaN detection
    if (typeof v === "number" && Number.isNaN(v)) return true;
    if (treatEmptyStringAsMissing && typeof v === "string" && v.trim() === "") return true;
    return false;
  };

  // Iterate columns
  for (const col of df.columns) {
    // get column values array
    const series = df.column(col);
    const values = series.values; // plain JS array

    // identify non-missing values
    const nonMissing = values.filter((v) => !isMissing(v));

    if (nonMissing.length === 0) {
      // Nothing to compute mode from; skip filling
      continue;
    }

    // Heuristic: consider column categorical if at least one non-missing is string or boolean
    const hasString = nonMissing.some((v) => typeof v === "string");
    const hasBool = nonMissing.some((v) => typeof v === "boolean");

    if (!hasString && !hasBool) {
      // Not treated as categorical (e.g., numeric continuous). Skip.
      continue;
    }

    // Compute frequencies (mode)
    const freq = new Map();
    for (const v of nonMissing) {
      // Use JSON.stringify for keys to distinguish e.g. different string forms, booleans etc.
      const key = typeof v === "string" ? v : String(v);
      freq.set(key, (freq.get(key) || 0) + 1);
    }

    // Find mode (most frequent)
    let modeKey = null;
    let modeCount = -1;
    for (const [k, c] of freq.entries()) {
      if (c > modeCount) {
        modeCount = c;
        modeKey = k;
      }
    }

    // Convert modeKey back to original typed value if possible:
    // If any original non-missing had same string and was boolean, handle booleans specifically:
    let modeValue = modeKey;
    // If any nonMissing value is boolean and modeKey is "true"/"false", convert to boolean
    if (hasBool && (modeKey === "true" || modeKey === "false")) {
      modeValue = modeKey === "true";
    }

    // Build new column with missing replaced by mode
    const filled = values.map((v) => (isMissing(v) ? modeValue : v));

    // Replace column in DataFrame
    // danfo.js: df.addColumn(colName, values, { inplace: true }) can be used, but addColumn throws if name exists
    // So we set via df.loc or create a new DataFrame column mapping
    df.addColumn(col, filled, { inplace: true });
  }

  return df;
}

