async function splitTupleColumn(db, tableName, tupleColumn, newColA, newColB) {
    // Create a temporary table with the split columns
    await db.execute(`
        CREATE TEMP TABLE temp_split AS
        SELECT
            *,
            ${tupleColumn}[0] AS ${newColA},
            ${tupleColumn}[1] AS ${newColB}
        FROM ${tableName}
    `);

    // Drop the original tuple column and rename the new columns
    await db.execute(`
        ALTER TABLE ${tableName}
        DROP COLUMN ${tupleColumn},
        RENAME COLUMN ${newColA} TO ${tupleColumn},
        RENAME COLUMN ${newColB} TO ${tupleColumn}_2
    `);

    // Update the table to include the new columns from temp_split
    await db.execute(`
        UPDATE ${tableName}
        SET
            ${tupleColumn} = temp_split.${newColA},
            ${tupleColumn}_2 = temp_split.${newColB}
        FROM temp_split
    `);

