function sortByReference(A, B, options = {}) {
  const { key = null, threshold = 0.6 } = options;

  // Create a Map for O(1) position lookup in B
  const positionMap = new Map();
  B.forEach((item, index) => {
    const value = key ? item[key] : item;
    positionMap.set(value, index);
  });

  // Create Fuse.js index for efficient fuzzy matching on large B
  const searchableB = key
    ? B.map((item) => ({ value: item[key], original: item }))
    : B.map((item) => ({ value: item }));

  const fuse = new Fuse(searchableB, {
    keys: ['value'],
    threshold: threshold,
    useExtendedSearch: true,
    ignoreLocation: true,
    minMatchCharLength: 1,
  });

  // Partition A into matched and unmatched items
  const unmatched = [];
  const matched = [];

  A.forEach((item) => {
    const value = key ? item[key] : item;

    // First try exact match in Map (O(1))
    if (positionMap.has(value)) {
      matched.push({
        item,
        position: positionMap.get(value),
      });
    } else {
