 * @param {Array<string>} headers - Column labels/headers
 * @param {Array<string>} groupKeys - Labels to group by (unique identifiers for each group)
 * @param {Object} groupMapping - Maps column header to group key
 * @returns {Object} Object with group keys as properties and summed values as values
 */
function groupColumnsAndSum(data, headers, groupMapping) {
  // Create a Polars DataFrame from the 2D array
  const df = pl.DataFrame(
    Object.fromEntries(
      headers.map((header, idx) => [
        header,
        data.map(row => row[idx])
      ])
    )
  );

  // Group columns by their mapped group keys
  const groups = {};

  for (const [columnHeader, groupKey] of Object.entries(groupMapping)) {
    if (!groups[groupKey]) {
      groups[groupKey] = [];
    }
    groups[groupKey].push(columnHeader);
  }

  // Compute sums for each group
  const result = {};

  for (const [groupKey, columns] of Object.entries(groups)) {
    const selectedDf = df.select(columns);
    const rowSums = selectedDf.toArray().map(row => 
      row.reduce((sum, val) => sum + (typeof val === 'number' ? val : 0), 0)
    );
    result[groupKey] = rowSums;
  }

  return result;
}

