```javascript
import * as pl from "polars";

function removeUnnamedColumns(df0) {
  // Get all column names
  const columnNames = df0.columns;

  // Filter out columns that start with "Unnamed"
  const columnsToKeep = columnNames.filter(col => !col.startsWith("Unnamed"));

  // Select only the columns we want to keep
  return df0.select(columnsToKeep);
}

// Example usage:
