    this._keyFn = keyFn || TinyHashSet.defaultKeyFn;
    for (const v of iterable) this.add(v);
  }

  add(value) {
    const k = this._keyFn(value);
    if (!this._map.has(k)) this._map.set(k, value);
    return this;
  }

  has(value) {
    return this._map.has(this._keyFn(value));
  }

  get size() {
    return this._map.size;
  }

  // Default stable key function: distinguishes primitives and deterministically serializes objects
  static defaultKeyFn(value) {
    if (value === null) return 'null';
    const t = typeof value;
    if (t === 'string' || t === 'number' || t === 'boolean' || t === 'undefined' || t === 'symbol') {
      return `${t}:${String(value)}`;
    }
    // For objects/functions, use stable stringify
    return 'obj:' + TinyHashSet._stableStringify(value);
  }

  // Deterministic JSON stringify that sorts object keys (simple, handles arrays/objects/primitives)
  static _stableStringify(value) {
    if (value === null) return 'null';
    const t = typeof value;
    if (t === 'string') return JSON.stringify(value);
    if (t === 'number' || t === 'boolean' || t === 'undefined') return String(value);
    if (Array.isArray(value)) {
