    // objects and functions: iterate sorted keys; functions use toString()
    if (t === 'function') return JSON.stringify(value.toString());
    const keys = Object.keys(value).sort();
    return '{' + keys.map(k => JSON.stringify(k) + ':' + TinyHashSet._stableStringify(value[k])).join(',') + '}';
  }
