 * @param {Array<any>} lst1 - Sequence defining the desired order
 * @returns {Array<[any, any]>} - Reordered tuples following lst1's order
 */
function reorderTuples(lst0, lst1) {
  // Create a Map for O(1) lookup of indices in lst1 for ordering
  const orderMap = new Map(lst1.map((item, index) => [item, index]));

  // Sort lst0 based on the order defined in lst1
  // Tuples whose first element appears in lst1 are sorted by that order
  // Tuples not in lst1 are placed at the end in their original relative order
  const reordered = lst0.sort((tupleA, tupleB) => {
    const keyA = tupleA[0];
    const keyB = tupleB[0];

    const indexA = orderMap.has(keyA) ? orderMap.get(keyA) : Infinity;
    const indexB = orderMap.has(keyB) ? orderMap.get(keyB) : Infinity;

    return indexA - indexB;
  });

  return reordered;
}

