 */
function sortByCustomOrder(
  records,
  key,
  valueSequence,
  options = {}
) {
  const {
    caseSensitive = true,
    placement = 'end'
  } = options;

  // Create a Map for O(1) lookup of positions
  const positionMap = new Map(
    valueSequence.map((value, index) => [
      caseSensitive ? value : String(value).toLowerCase(),
      index
    ])
  );

  // Create a comparator function using the position map
