 * @returns {number} weighted average (NaN if no valid rows or sum of weights is zero)
 */
export function weightedAverage(dataset, colValues, colWeights, options = {}) {
  const { skipNaN = true } = options;

  // Accept either an Arquero table or a plain array of objects
  const tbl = (dataset && typeof dataset.column === "function") ? dataset : aq.table(dataset);

  // Extract column arrays
  const vals = tbl.column(colValues);
  const wts = tbl.column(colWeights);

