  }

  let num = 0;
  let denom = 0;
  for (let i = 0; i < vals.length; i++) {
    const v = Number(vals[i]);
    const w = Number(wts[i]);

    const vIsValid = Number.isFinite(v);
    const wIsValid = Number.isFinite(w);

    if (skipNaN) {
