# Category Encoding Function using Polars (2024)

```javascript
import * as pl from 'polars';

/**
 * Maps each unique category in column 'col0' to integer codes
 * and replaces the original values with numeric codes.
 * 
 * @param {pl.DataFrame} df0 - Input DataFrame with a 'col0' column containing categories
 * @returns {pl.DataFrame} - DataFrame with 'col0' values replaced by integer codes
 */
function encodeCategoricalColumn(df0) {
  // Get unique values from col0 and create a mapping
  const uniqueCategories = df0
    .select(pl.col('col0'))
    .unique()
    .sort('col0')
    .to_array()
    .map((row, index) => [row[0], index])
    .reduce((map, [category, code]) => {
      map[category] = code;
      return map;
    }, {});

  // Create a mapping expression using when-then chains
  let mapExpr = pl.when(pl.col('col0').eq(Object.keys(uniqueCategories)[0]))
    .then(pl.lit(uniqueCategories[Object.keys(uniqueCategories)[0]]));

  for (let i = 1; i < Object.keys(uniqueCategories).length; i++) {
    const category = Object.keys(uniqueCategories)[i];
    mapExpr = mapExpr
      .when(pl.col('col0').eq(category))
      .then(pl.lit(uniqueCategories[category]));
  }

  // Apply the mapping and return the modified DataFrame
  return df0.with_columns(
    mapExpr.otherwise(pl.lit(null)).alias('col0_encoded')
  )
  .drop('col0')
  .rename({ 'col0_encoded': 'col0' });
}

