Code (CommonJS):

const dfd = require("danfojs-node");

/**
 * zscoreNormalize
 * - Accepts: a danfo DataFrame, or any input supported by dfd.DataFrame constructor
 * - Returns: a new danfo DataFrame in which every numeric column has been z-score normalized
 *
 * Behavior:
 * - For numeric columns: (x - mean) / std
 * - If std === 0 (constant column): all normalized values set to 0
 * - Non-numeric / all-missing columns are returned unchanged
 *
 * Example inputs accepted:
 * - array of objects: [{a:1,b:2}, {a:3,b:4}]
 * - array of arrays with header: { columns: [...], data: [...] } or use DataFrame constructor forms
 */
function zscoreNormalize(df0) {
  // Convert to danfo DataFrame if not already
  const df = (df0 instanceof dfd.DataFrame) ? df0.copy() : new dfd.DataFrame(df0);

  const cols = df.columns;
  // We'll build an object of normalized arrays, then create a new DataFrame
  const normalizedColumns = {};

  for (const col of cols) {
    // Get series for the column
    const series = df.column(col);
    const values = series.values;

    // Try to coerce values to numbers where sensible (null/undefined -> NaN)
    const numericValues = values.map(v => {
      if (v === null || v === undefined || v === "") return NaN;
      const n = Number(v);
      return Number.isFinite(n) ? n : NaN;
    });

    // If column is all-NaN (non-numeric), preserve original values as-is
    const allNaN = numericValues.every(v => Number.isNaN(v));
    if (allNaN) {
      normalizedColumns[col] = values.slice(); // copy original
      continue;
    }

    // compute mean and std using numeric values (ignore NaNs for mean/std)
    const validVals = numericValues.filter(v => !Number.isNaN(v));
    const mean = validVals.reduce((a, b) => a + b, 0) / validVals.length;
    const variance = validVals.reduce((acc, v) => acc + (v - mean) ** 2, 0) / validVals.length;
    const std = Math.sqrt(variance);

    // produce normalized values, preserving original missing (set to null)
    const norm = numericValues.map(v => {
      if (Number.isNaN(v)) return null;
      if (std === 0) return 0; // constant column -> set normalized to 0
      return (v - mean) / std;
    });

    normalizedColumns[col] = norm;
  }

  // Return a new DataFrame with normalized columns
  return new dfd.DataFrame(normalizedColumns);
}

