  // Create a sample DataFrame
  const df0 = new dfd.DataFrame({
    Date: ["2024-01-15", "2024-03-20", "2024-02-10", "2024-12-01"],
    Value: [100, 200, 150, 300],
  });

  const result = await findDateRange(df0);
  console.log("Date Range Analysis:");
