import dfd from "danfo-js-node";

/**
 * Adds a conditional column to a DataFrame based on a threshold value
 * @param {dfd.DataFrame} df0 - The input DataFrame
 * @param {string} columnName - Name of the source column (e.g., 'A')
 * @param {number} val0 - The threshold value
 * @param {string} label_high - Label for values > threshold
 * @param {string} label_low - Label for values <= threshold
 * @returns {dfd.DataFrame} - DataFrame with new 'col0' column added
 */
function addConditionalColumn(df0, columnName, val0, label_high, label_low) {
  // Extract the source column and create conditional values
  const columnData = df0[columnName].values;
  const newColumn = columnData.map(value => 
    value > val0 ? label_high : label_low
  );

  // Add the new column to the DataFrame
  df0.addColumn({ column: "col0", value: newColumn });

  return df0;
}

