```javascript
/**
 * Unpivots specified columns from a DataFrame
 * @param {Object} df0 - Danfo.js DataFrame
 * @param {Array<string>} lst0 - List of column names to unpivot
 * @param {string} var0 - Name of the column to store original column names (default: 'variable')
 * @param {string} var1 - Name of the column to store values (default: 'value')
 * @returns {Object} - New unpivoted DataFrame
 */
function unpivot(df0, lst0, var0 = 'variable', var1 = 'value') {
  const dfd = require('danfo-js-node'); // For Node.js
  // or use: import * as dfd from 'danfo-js-node'; for ES modules

  const unpivotedData = [];

  // Get all columns not being unpivoted (id vars)
  const idVars = df0.columns.filter(col => !lst0.includes(col));

  // Iterate through each row
  for (let i = 0; i < df0.shape[0]; i++) {
    const row = df0.iloc({ rows: [i] });

    // Get id variable values for this row
    const idVarValues = {};
    idVars.forEach(col => {
      idVarValues[col] = row[col].values[0];
    });

    // Unpivot each specified column
    lst0.forEach(col => {
      unpivotedData.push({
        ...idVarValues,
        [var0]: col,
        [var1]: row[col].values[0]
      });
    });
  }

  // Convert array of objects back to DataFrame
  return new dfd.DataFrame(unpivotedData);
}

// Example usage:
