function normalizeDataFrame(df0) {
  /**
   * Normalize each column of a 2D table to scale between 0 and 1
   * @param {Array<Array>} df0 - Input 2D array
   * @returns {Array<Array>} Normalized 2D array
   */

  // Handle empty input
  if (!df0 || df0.length === 0) return df0;

  const numCols = df0[0].length;

  // Calculate min and max for each column
  const minValues = Array(numCols).fill(Infinity);
  const maxValues = Array(numCols).fill(-Infinity);

  for (const row of df0) {
    for (let col = 0; col < numCols; col++) {
      minValues[col] = Math.min(minValues[col], row[col]);
      maxValues[col] = Math.max(maxValues[col], row[col]);
    }
  }

  // Normalize each value
  return df0.map((row) =>
    row.map((value, col) => {
      const range = maxValues[col] - minValues[col];
      return range === 0 ? 0 : (value - minValues[col]) / range;
    })
  );
}

// Example usage:
const data = [
  [10, 100, 5],
  [20, 200, 15],
  [30, 150, 10],
  [40, 250, 20]
];

console.log(normalizeDataFrame(data));
```

Both approaches perform **min-max normalization** (also called feature scaling), which transforms values to the range [0, 1] using the formula: `(x - min) / (max - min)`.

