# Remove Consecutive Duplicate Rows using Danfo.js

Here's a self-contained JavaScript function using **Danfo.js** (a 2024+ library for data manipulation):

```javascript
const dfd = require('danfo-js-node'); // npm install danfo-js-node

/**
 * Remove consecutive duplicate rows from a DataFrame
 * Preserves only the first row in each sequence of consecutive duplicates
 * @param {dfd.DataFrame} df0 - Input DataFrame
 * @returns {dfd.DataFrame} - DataFrame with consecutive duplicates removed
 */
function removeConsecutiveDuplicates(df0) {
  // Convert DataFrame to array of row objects for comparison
  const data = df0.values; // 2D array
  const columns = df0.columns;

  if (data.length === 0) {
    return df0;
  }

  // Track indices of rows to keep
  const indicesToKeep = [0]; // Always keep the first row

  // Compare each row with the previous one
  for (let i = 1; i < data.length; i++) {
    const currentRow = data[i];
    const previousRow = data[i - 1];

    // Check if rows are identical
    const isIdentical = currentRow.every(
      (val, idx) => {
        // Handle NaN comparison
        if (Number.isNaN(val) && Number.isNaN(previousRow[idx])) {
          return true;
        }
        return val === previousRow[idx];
      }
    );

    // If not identical, keep this row
    if (!isIdentical) {
      indicesToKeep.push(i);
    }
  }

  // Return new DataFrame with only the kept rows
  return df0.iloc({ rows: indicesToKeep });
}

