import ss from 'simple-statistics';

/**
 * Computes the moving average of a numeric sequence
 * @param {number[]} lst0 - The input numeric sequence
 * @param {number} window_size - The size of the moving window
 * @returns {number[]} - Array of moving averages
 */
function movingAverage(lst0, window_size) {
  if (window_size <= 0 || !Number.isInteger(window_size)) {
    throw new Error('window_size must be a positive integer');
  }

  if (lst0.length < window_size) {
    throw new Error('sequence length must be >= window_size');
  }

  const result = [];

  for (let i = 0; i <= lst0.length - window_size; i++) {
    const window = lst0.slice(i, i + window_size);
    const avg = ss.mean(window);
    result.push(avg);
  }

  return result;
}

// Example usage:
const data = [10, 20, 30, 40, 50, 60, 70];
const windowSize = 3;

const movingAverages = movingAverage(data, windowSize);
console.log(movingAverages);
// Output: [20, 30, 40, 50, 60]
```

