/**
 * Adds a new column to a DataFrame by splitting values from an existing column
 * @param {dfd.DataFrame} df0 - The input DataFrame
 * @param {string} sourceCol - The column to split from (default: 'var0')
 * @param {string} newCol - The name of the new column (default: 'var1')
 * @param {string|RegExp} delimiter - The delimiter to split by (default: ',')
 * @param {number} index - Which part to extract after split (default: 0)
 * @returns {dfd.DataFrame} - The DataFrame with the new column added
 */
function addSplitColumn(
  df0,
  sourceCol = "var0",
  newCol = "var1",
  delimiter = ",",
  index = 0
) {
  // Get the source column as an array
  const sourceData = df0[sourceCol].values;

  // Split each value and extract the specified index
  const splitData = sourceData.map((value) => {
    const parts = value.toString().split(delimiter);
    return parts[index] ? parts[index].trim() : "";
  });

  // Add the new column to the DataFrame
  df0.addColumn({ column: newCol, value: splitData });

  return df0;
}

