```javascript
const dfd = require('danfo-js-node');

/**
 * Eliminates duplicates based on fields A and B,
 * keeping only the entry with the maximum C value
 * for each unique combination of A and B.
 * 
 * @param {dfd.DataFrame} df0 - Input DataFrame
 * @returns {dfd.DataFrame} - Deduplicated DataFrame
 */
function deduplicateByMaxC(df0) {
  // Sort by A, B (ascending) and C (descending)
  // This ensures max C comes first for each A,B combination
  const sorted = df0.sort_values({
    by: ['A', 'B', 'C'],
    ascending: [true, true, false]
  });

  // Drop duplicates keeping only first occurrence
  // (which is the max C due to our sort)
  const deduplicated = sorted.drop_duplicates({
    subset: ['A', 'B'],
    keep: 'first'
  });

  return deduplicated;
}

// Example usage:
const data = {
  'A': [1, 1, 1, 2, 2, 3],
  'B': [10, 10, 10, 20, 20, 30],
  'C': [100, 50, 75, 200, 150, 300]
};

