async function computeMeanAcrossTables(lst0) {
  // Import simple-statistics library
  const ss = await import('simple-statistics');

  if (!lst0 || lst0.length === 0) {
    throw new Error('Input list is empty');
  }

  const firstTable = lst0[0];
  const rows = firstTable.length;
  const cols = firstTable[0].length;

  // Validate all tables have same dimensions
  for (const table of lst0) {
    if (table.length !== rows || table[0].length !== cols) {
      throw new Error('All tables must have the same dimensions');
    }
  }

  // Compute mean for each position
  const meanTable = [];

  for (let i = 0; i < rows; i++) {
    meanTable[i] = [];

    for (let j = 0; j < cols; j++) {
      // Collect corresponding entries from all tables
      const values = lst0.map(table => table[i][j]);

      // Compute mean using simple-statistics
      const mean = ss.mean(values);
      meanTable[i][j] = mean;
    }
  }

  return meanTable;
}

