 * @param {danfo.DataFrame} df1 - Source dataframe with new values
 * @param {Array<string>} columns - Column names to update (if empty, updates all common columns)
 * @param {string} matchColumn - Column to match rows by (default: index matching)
 * @returns {danfo.DataFrame} Updated dataframe
 */
async function updateDataFrameCells(df0, df1, columns = [], matchColumn = null) {
  // Import Danfo.js (2024+)
  const dfd = await import('https://cdn.jsdelivr.net/npm/danfo.js@2.0.0/dist/index.esm.min.js');

  // Copy df0 to avoid mutation
  let result = df0.copy();

  // Determine columns to update
  const columnsToUpdate = columns.length > 0 
    ? columns 
    : df0.columns.filter(col => df1.columns.includes(col));

  if (matchColumn) {
    // Update based on matching column values
    for (let col of columnsToUpdate) {
      if (!df1.columns.includes(col)) continue;

      for (let i = 0; i < df0.shape[0]; i++) {
        const matchValue = result.iloc({rows: [i]}).values[0][result.columns.indexOf(matchColumn)];

        // Find matching row in df1
        const matchingRowIndex = df1.values.findIndex(row => 
          row[df1.columns.indexOf(matchColumn)] === matchValue
        );

        if (matchingRowIndex !== -1) {
          const newValue = df1.iloc({rows: [matchingRowIndex]})[col].values[0];
          result.loc({rows: [i], columns: [col]}) = newValue;
