  // But here's how you'd use a 2024+ tokenizer library:

  const Tokenizer = require('@tokenizers/js').Tokenizer;

  try {
    // Tokenize the text into words
    const tokens = text.toLowerCase().split(/\s+/);
    const searchTermLower = searchTerm.toLowerCase();

    // Find the index of the search term
    const searchIndex = tokens.findIndex(token => 
      token.includes(searchTermLower) || searchTermLower.includes(token)
    );

    if (searchIndex === -1) {
      return {
        found: false,
        before: Array(contextWords).fill(null),
        after: Array(contextWords).fill(null),
        message: `"${searchTerm}" not found in text`
      };
