    const beforeWords = tokens.slice(beforeStart, searchIndex);
    const before = [
      ...Array(contextWords - beforeWords.length).fill(null),
      ...beforeWords
    ];

    // Extract words after
    const afterEnd = Math.min(tokens.length, searchIndex + 1 + contextWords);
    const afterWords = tokens.slice(searchIndex + 1, afterEnd);
    const after = [
      ...afterWords,
      ...Array(contextWords - afterWords.length).fill(null)
    ];

    return {
      found: true,
      before: before,
      after: after,
      foundTerm: tokens[searchIndex]
    };

  } catch (error) {
    console.error('Error processing text:', error);
    return {
      found: false,
      before: Array(contextWords).fill(null),
      after: Array(contextWords).fill(null),
      error: error.message
    };
  }
